using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Weil.ZetaBridge;

internal sealed class OriginalSignedCompressedFourierDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Weil/ZetaBridge/OriginalSignedCompressedFourier.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Literal Lebesgue Ioc compression of all signed complex Fourier modes. The interval Fourier calculation is classical, as in Connes--Consani--Moscovici Lemma 2.3 and Section 4. The phase is (-1)^n, the physical interval is (-L/2,L/2], and T_h evaluates x-h. This is only the compressed-translation component; it does not identify the Gamma or full nuX form.",
        H("Original Signed Compressed Fourier"),
        Blocks(
                Paragraph(Text("Literal Lebesgue Ioc compression of all signed complex Fourier modes. The interval Fourier calculation is classical, as in Connes--Consani--Moscovici Lemma 2.3 and Section 4. The phase is (-1)^n, the physical interval is (-L/2,L/2], and T_h evaluates x-h. This is only the compressed-translation component; it does not identify the Gamma or full nuX form.")),
                Describe.Lean(DescribeId.Create("frequency"),
                    DeclarationHandle.Create(Owner + "frequency"), H("frequency"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The frequency is 2*pi*n/L for signed integers n and positive physical length L."))), DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("mode"),
                    DeclarationHandle.Create(Owner + "mode"), H("mode"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The normalized profile is exp(i*(2*pi*n/L)*(x+L/2))/sqrt(L). The shifted origin incorporates (-1)^n without changing Lebesgue normalization."))), DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("entry"),
                    DeclarationHandle.Create(Owner + "entry"), H("entry"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The conjugate-first physical correlation uses the existing pairing with compression parameter -h. Both inner and outer Ioc indicators are literal."))), DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("mode-continuous"),
                    DeclarationHandle.Create(Owner + "mode_continuous"), H("mode continuous"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("This consumed helper supplies continuity of the unextended profile for the finite integral expansion."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("normalization-dictionary"),
                    DeclarationHandle.Create(Owner + "normalization_dictionary"), H("normalization dictionary"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("For L>0 the profile agrees exactly with (-1)^n times the existing OriginalEvenCosineComplete.character at half-length L/2 divided by sqrt(L). Only that exponential character definition is reused, with no even-sector inference."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("entry-nonneg"),
                    DeclarationHandle.Create(Owner + "entry_nonneg"), H("entry nonneg"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("For 0<=h<=L direct integration on (h-L/2,L/2] gives the diagonal overlap factor and the guarded off-diagonal exponential quotient. The denominator n-m is used only when m differs from n. Both zero and endpoint shifts are included."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("pairing-line"),
                    DeclarationHandle.Create(Owner + "pairing_line"), H("pairing line"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The existing compressed pairing equals the line pairing of the two literal zero extensions. This identity is used by both the adjoint calculation and the displacement energy proof."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("entry-adjoint"),
                    DeclarationHandle.Create(Owner + "entry_adjoint"), H("entry adjoint"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("A line translation of the original integral yields C_mn(-h)=conj(C_nm(h)) for every real h. No parity of the profiles is assumed."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("entry-disjoint"),
                    DeclarationHandle.Create(Owner + "entry_disjoint"), H("entry disjoint"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The Ioc overlap is empty for |h|>=L, including the two touching endpoint shifts. This is proved before any divided difference is used."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("matrix"),
                    DeclarationHandle.Create(Owner + "matrix"), H("matrix"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The explicit all-shift complex matrix has separate disjoint, nonnegative-shift and negative-shift branches. Its diagonal and off-diagonal cases remain separate to guard the removable singularity."))), DescribeRole.Definition),
                Describe.Lean(DescribeId.Create("entry-eq-matrix"),
                    DeclarationHandle.Create(Owner + "entry_eq_matrix"), H("entry eq matrix"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The actual original compressed integral is evaluated by the explicit matrix for every signed pair and every real shift. Positive length is the only length hypothesis."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("entry-paired"),
                    DeclarationHandle.Create(Owner + "entry_paired"), H("entry paired"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("For 0<=h<=L the diagonal sum is 2*(1-h/L)*cos(w_n*h); for m!=n it is (sin(w_m*h)-sin(w_n*h))/(pi*(n-m)). The result follows by adding the two complex correlations after fixing orientation from their integrals."))), DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("entry-norm-le-one"),
                    DeclarationHandle.Create(Owner + "entry_norm_le_one"), H("entry norm le one"),
                    StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                    Blocks(Paragraph(Text("The norm is bounded by integrating the constant product amplitude on the literal overlap. The desired contraction is not supplied as an assumption."))), DescribeRole.Theorem))));
}
